            string expected = string.Format("{0} - {1}", _choiceCreator.Ticket.MatchCode, _choiceCreator.TicketHelperStub.GetHorseTeamNameById(_choiceCreator.Ticket.HomeId, _choiceCreator.Ticket.AwayId));
